/**
 * plates.ts — הסביבה האמיתית (מרכז נווה זמר והשכונה) כפנורמות שנאפו ב-Blender Cycles.
 * לכל אקט מיקום מצלמה קבוע (המצלמה רק מסתובבת/משנה FOV בזמן שהבמה גלויה), ולכן פנורמה
 * equirect חלקית שממורכזת במצלמה מדויקת פרספקטיבית: ריאליזם של path-tracing בעלות GPU אפסית.
 * המודל והרינדור: scripts/blender/centre.py (+ building_v2.py, site_osm.py). הלוח, המלכה והכלים בזמן אמת מעל.
 *
 * צבע: הפנורמות נאפות עם המראה הסופי (AgX) — כאן הן עוקפות את ה-tone mapping. בנתיב הישיר: toneMapped=false.
 * בנתיב ה-composer (בלום הכתר בסיום) ה-OutputPass ממפה את כל הפריים ב-ACES, ולכן השיידר מחיל מראש את ההופכי
 * המדויק של ACES (uInv=1) — התוצאה על המסך זהה 1:1 בשני הנתיבים.
 * השלט והמלכה הקטנה אפויים בתוך הפנורמות (תאורה/הסתרה נכונות); לאנגלית (עולם משוקף) יש גרסאות ‎-en‏ עם לוגו הפוך מראש.
 */
import * as THREE from 'three';

interface PlateDef { name: string; f: [number, number]; lon: number; lat: [number, number]; pos: [number, number, number]; en?: boolean; }
export interface Plates { update(p: number, glow: number, viaComposer: boolean, exposure: number): void; setPortrait(portrait: boolean): void; envMap: THREE.Texture | null; }

const R = 120; // < camera.far (160)

function section(d: PlateDef) {
  const NX = 48, NY = 24;
  const lon = THREE.MathUtils.degToRad(d.lon), la0 = THREE.MathUtils.degToRad(d.lat[0]), la1 = THREE.MathUtils.degToRad(d.lat[1]);
  const [fx, fz] = d.f; const lx = fz, lz = -fx; // שמאלה מכיוון המבט
  const pos: number[] = [], uv: number[] = [], idx: number[] = [];
  for (let j = 0; j <= NY; j++) for (let i = 0; i <= NX; i++) {
    const u = i / NX, v = j / NY;
    const lo = lon - u * 2 * lon; // u=0 → שמאל (lon חיובי); Cycles ליניארי ב-lon וב-lat
    const la = la0 + v * (la1 - la0);
    const c = Math.cos(la);
    pos.push(R * c * (Math.cos(lo) * fx + Math.sin(lo) * lx), R * Math.sin(la), R * c * (Math.cos(lo) * fz + Math.sin(lo) * lz));
    uv.push(u, v);
  }
  for (let j = 0; j < NY; j++) for (let i = 0; i < NX; i++) {
    const a = j * (NX + 1) + i, b = a + 1, c = a + NX + 1, e = c + 1;
    idx.push(a, b, c, b, e, c);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  g.setIndex(idx);
  return g;
}

const FRAG = `uniform sampler2D map;uniform float uGain;uniform float uInv;uniform float uExp;varying vec2 vUv;
vec3 invFit(vec3 y){y=clamp(y,0.,.985);vec3 A=.983729*y-1.,B=.432951*y-.0245786,C=.238081*y+.000090537;return (-B-sqrt(max(B*B-4.*A*C,0.)))/(2.*A);}
void main(){vec3 c=texture2D(map,vUv).rgb*uGain;
if(uInv>.5){ // ההופכי של ACESFilmicToneMapping של three (כולל החשיפה) — ה-OutputPass יחזיר בדיוק את c
mat3 inM=mat3(.59719,.07600,.02840,.35458,.90834,.13383,.04823,.01566,.83777);
mat3 outM=mat3(1.60475,-.10208,-.00327,-.53108,1.10813,-.07276,-.07367,-.00605,1.07602);
c=inverse(inM)*invFit(inverse(outM)*c)*(.6/uExp);gl_FragColor=vec4(c,1.);}
else{gl_FragColor=vec4(c,1.);
#include <colorspace_fragment>
}}`;

export async function loadPlates(base: string, scene: THREE.Scene, camera: THREE.Camera, renderer: THREE.WebGLRenderer,
  S: number, portrait: boolean, wake: () => void, hdr: boolean | Promise<boolean> = true): Promise<Plates> {
  const defs: PlateDef[] = await (await fetch(base + 'env/plates.json')).json();
  // פענוח התמונה מחוץ ל-main thread (ImageBitmap) — אותם פיקסלים בדיוק (flipY נעשה בפענוח, כמו TextureLoader),
  // בלי משימה ארוכה של פענוח+העלאה בזמן הטעינה (Lighthouse: TBT). נפילה ל-TextureLoader כשאין createImageBitmap.
  const bitmaps = typeof createImageBitmap === 'function';
  const bmLoader = bitmaps ? new THREE.ImageBitmapLoader().setOptions({ imageOrientation: 'flipY', premultiplyAlpha: 'none', colorSpaceConversion: 'none' }) : null;
  const texLoader = new THREE.TextureLoader();
  const load = (url: string) => new Promise<THREE.Texture>((res, rej) => {
    if (bmLoader) bmLoader.load(url, (bm) => { const t = new THREE.Texture(bm as ImageBitmap); t.flipY = false; t.needsUpdate = true; res(t); }, undefined, rej);
    else texLoader.load(url, res, undefined, rej);
  });
  const fileOf = (d: PlateDef) => base + 'env/' + d.name + (S < 0 && d.en ? '-en' : '') + '.webp';
  const group = new THREE.Group();
  group.scale.x = S; // LTR: כל העולם משוקף
  scene.add(group);

  let mine: PlateDef[] = [];
  let meshes: (THREE.Mesh | null)[] = [];
  let pending: boolean[] = [];
  let shown = -1;
  // העלאה ל-GPU ברצועות: פנורמה של 4096×2700 בקריאת texImage2D אחת = משימה של ~100-130ms, ונופלת באמצע הגלילה
  // (טעינה מוקדמת של האקט הבא). עכשיו: טקסטורה ריקה בגודל מלא ו-8 רצועות, עם החזרת שליטה לדפדפן בין רצועה לרצועה.
  // אותם פיקסלים בדיוק (ה-ImageBitmap כבר הפוך בפענוח, אותו פורמט sRGB, אותם פילטרים). בלי WebGL2/ImageBitmap — העלאה אחת כמו קודם.
  const STRIPS = 8;
  const yieldMain = () => new Promise<void>((r) => { const sch = (globalThis as any).scheduler; if (sch?.yield) sch.yield().then(r); else setTimeout(r, 0); });
  const upload = async (tex: THREE.Texture): Promise<THREE.Texture> => {
    const img = tex.image as ImageBitmap;
    if (!renderer.capabilities.isWebGL2 || typeof ImageBitmap === 'undefined' || !(img instanceof ImageBitmap)) {
      tex.colorSpace = THREE.SRGBColorSpace; tex.generateMipmaps = false; tex.minFilter = THREE.LinearFilter;
      renderer.initTexture(tex);
      return tex;
    }
    const w = img.width, h = img.height;
    const dst = new THREE.DataTexture(null, w, h, THREE.RGBAFormat, THREE.UnsignedByteType);
    dst.colorSpace = THREE.SRGBColorSpace; dst.generateMipmaps = false; dst.flipY = false;
    dst.minFilter = THREE.LinearFilter; dst.magFilter = THREE.LinearFilter;
    dst.source.dataReady = false; // הקצאת זיכרון בלבד (texStorage2D) — התוכן מגיע ברצועות
    dst.needsUpdate = true;
    renderer.initTexture(dst);
    const rows = Math.ceil(h / STRIPS);
    for (let y = 0; y < h; y += rows) {
      const y1 = Math.min(h, y + rows);
      renderer.copyTextureToTexture(tex, dst, new THREE.Box2(new THREE.Vector2(0, y), new THREE.Vector2(w, y1)), new THREE.Vector2(0, y));
      if (y1 < h) await yieldMain();
    }
    img.close?.(); tex.dispose();
    return dst;
  };
  const mk = (i: number, tex: THREE.Texture) => {
    const m = new THREE.Mesh(section(mine[i]), new THREE.ShaderMaterial({
      uniforms: { map: { value: tex }, uGain: { value: 1 }, uInv: { value: 0 }, uExp: { value: 1 } },
      vertexShader: 'varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',
      fragmentShader: FRAG, side: THREE.DoubleSide, fog: false, depthWrite: false, depthTest: false, toneMapped: false,
    }));
    m.renderOrder = -10; m.frustumCulled = false; m.visible = false;
    m.userData.plate = true; // הבמה לא נוגעת בנראוּת שלהן (הן מוצגות רק כשהאקט משתנה — מצב ישן לא מתוקן)
    group.add(m); meshes[i] = m; wake();
  };
  const drop = (i: number) => {
    const m = meshes[i]; if (!m) return;
    group.remove(m); m.geometry.dispose(); const mat = m.material as THREE.ShaderMaterial; (mat.uniforms.map.value as THREE.Texture).dispose(); mat.dispose();
    meshes[i] = null; if (shown === i) shown = -1;
  };
  const ensure = (i: number, set: PlateDef[]) => {
    if (i < 0 || i >= mine.length || meshes[i] || pending[i]) return;
    pending[i] = true;
    load(fileOf(mine[i])).then(upload).then((tex) => { if (set === mine) { pending[i] = false; mk(i, tex); } else tex.dispose(); }, () => { pending[i] = false; });
  };
  const pick = (p: boolean) => {
    for (let i = 0; i < meshes.length; i++) drop(i);
    const prefix = p ? 'p' : 'd';
    mine = defs.filter((d) => d.name[0] === prefix).sort((a, b) => a.name.localeCompare(b.name));
    meshes = mine.map(() => null); pending = mine.map(() => false); shown = -1;
  };
  pick(portrait);
  if (!mine.length) throw new Error('no plates');
  mk(0, await upload(await load(fileOf(mine[0])))); // האקט הראשון חייב להיטען לפני שמחליפים את העולם הפרוצדורלי (טעינה אחת — אותה טקסטורה משמשת)

  // השתקפויות: פנורמה מלאה שנאפתה ממרכז הלוח — הזהב והלכה משקפים את הבניין והשמיים האמיתיים
  // HDR (env.hdr — Cycles, רדיאנס לינארי אמיתי): השמש והשמיים חורגים מ-1, כך שלזהב ולמתכת השחורה יש היילייטים
  // אמיתיים ולא רק תמונה שטוחה של הסביבה. נפילה ל-env.webp (LDR) אם ה-HDR לא נטען.
  let envMap: THREE.Texture | null = null;
  const toEnv = (eq: THREE.Texture) => {
    eq.mapping = THREE.EquirectangularReflectionMapping;
    const pm = new THREE.PMREMGenerator(renderer); envMap = pm.fromEquirectangular(eq).texture; pm.dispose(); eq.dispose();
  };
  try {
    // טלפונים/שכבה נמוכה: env.webp (40KB) במקום ה-HDR (1MB). בשכבה המלאה ה-HDR נטען רק אחרי אינטראקציה ראשונה
    // (hdr = הבטחה מ-stage.ts) — עד אז מוצג הפוסטר, כך שהמגה-בייט לא מתחרה ב-LCP ולא יורד למי שלא זז בכלל.
    if (!(await hdr)) throw new Error('low tier');
    const { RGBELoader } = await import('three/examples/jsm/loaders/RGBELoader.js');
    // תקרה של 6 שניות — חיבור איטי מקבל את ה-LDR במקום לחכות
    const eq = await Promise.race([
      new RGBELoader().setDataType(THREE.HalfFloatType).loadAsync(base + 'env/env.hdr'),
      new Promise<never>((_, rej) => setTimeout(() => rej(new Error('hdr slow')), 6000)),
    ]);
    toEnv(eq);
  } catch {
    try { const eq = await load(base + 'env/env.webp'); eq.colorSpace = THREE.SRGBColorSpace; toEnv(eq); } catch { /* נשארים עם הסביבה הקיימת */ }
  }

  return {
    envMap,
    setPortrait(p) { if ((mine[0]?.name[0] === 'p') !== p) { pick(p); wake(); } },
    update(p, glow, viaComposer, exposure) {
      group.position.copy(camera.position);
      const want = Math.min(mine.length - 1, Math.max(0, Math.round(p)));
      ensure(want, mine); ensure(want + (p >= want ? 1 : -1), mine);
      for (let i = 0; i < meshes.length; i++) if (Math.abs(i - want) > 1) drop(i); // זיכרון GPU: רק האקט הנוכחי ושכניו
      let best = -1;
      for (let i = 0; i < meshes.length; i++) if (meshes[i] && (best < 0 || Math.abs(i - want) < Math.abs(best - want))) best = i;
      if (best !== shown) { if (shown >= 0 && meshes[shown]) meshes[shown]!.visible = false; if (best >= 0) meshes[best]!.visible = true; shown = best; }
      if (best >= 0) {
        const u = (meshes[best]!.material as THREE.ShaderMaterial).uniforms;
        u.uGain.value = 1 + 0.1 * glow; u.uInv.value = viaComposer ? 1 : 0; u.uExp.value = exposure;
      }
    },
  };
}
